package com.careflow.hospital.scheduling;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="doctor_schedule") public class DoctorSchedule {@Id @Column(name="schedule_id") private UUID id;@Column(name="doctor_id",nullable=false) private UUID doctorId;@Column(name="day_of_week",nullable=false) private int dayOfWeek;@Column(name="starts_at",nullable=false) private LocalTime startsAt;@Column(name="ends_at",nullable=false) private LocalTime endsAt;@Column(name="slot_duration_minutes",nullable=false) private int slotDurationMinutes;@Column(nullable=false) private boolean active;@Column(name="created_at",nullable=false) private Instant createdAt;protected DoctorSchedule(){}public DoctorSchedule(UUID doctorId,int day,LocalTime start,LocalTime end,int duration){id=UUID.randomUUID();this.doctorId=doctorId;dayOfWeek=day;startsAt=start;endsAt=end;slotDurationMinutes=duration;active=true;createdAt=Instant.now();}public void deactivate(){active=false;}public UUID getId(){return id;}public UUID getDoctorId(){return doctorId;}public int getDayOfWeek(){return dayOfWeek;}public LocalTime getStartsAt(){return startsAt;}public LocalTime getEndsAt(){return endsAt;}public int getSlotDurationMinutes(){return slotDurationMinutes;}public boolean isActive(){return active;}}
